-- Curated Tharparkar public-service catalog. Source names are public-directory records, not claims that contact details or current operation have been verified.
-- Coordinates are only settlement-centre reference points when explicitly marked approximate; missing coordinates stay NULL.
-- Sources are attributed in facility_data_sources and documented in docs/data-sources-tharparkar.md.
CREATE TABLE IF NOT EXISTS facility_data_sources (
    facility_id BIGINT PRIMARY KEY REFERENCES facilities(id) ON DELETE CASCADE,
    source_name VARCHAR(160) NOT NULL,
    source_url VARCHAR(1000) NOT NULL,
    source_record_id VARCHAR(120),
    verification_status VARCHAR(50) NOT NULL,
    location_precision VARCHAR(50) NOT NULL,
    coordinate_source_name VARCHAR(160),
    coordinate_source_url VARCHAR(1000),
    imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_facility_data_sources_status ON facility_data_sources(verification_status);

CREATE TEMPORARY TABLE communex_tharparkar_facility_seed (
    name VARCHAR(160) NOT NULL,
    category VARCHAR(60) NOT NULL,
    description VARCHAR(2000),
    address VARCHAR(500),
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    source_name VARCHAR(160) NOT NULL,
    source_url VARCHAR(1000) NOT NULL,
    source_record_id VARCHAR(120),
    verification_status VARCHAR(50) NOT NULL,
    location_precision VARCHAR(50) NOT NULL,
    coordinate_source_name VARCHAR(160),
    coordinate_source_url VARCHAR(1000)
) ON COMMIT DROP;


-- Insert only records not already present; never overwrite user-managed facilities.
SELECT s.name, s.category, s.description, s.address, s.latitude, s.longitude, FALSE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM communex_tharparkar_facility_seed s
WHERE NOT EXISTS (
    SELECT 1 FROM facilities f
    WHERE lower(f.name) = lower(s.name)
      AND lower(f.category) = lower(s.category)
      AND lower(coalesce(f.address, '')) = lower(coalesce(s.address, ''))
);

-- Attach source and precision metadata without changing FacilityResponse/API shape.
SELECT DISTINCT ON (f.id)
       f.id, s.source_name, s.source_url, s.source_record_id, s.verification_status, s.location_precision, s.coordinate_source_name, s.coordinate_source_url
FROM communex_tharparkar_facility_seed s
JOIN facilities f
  ON lower(f.name) = lower(s.name)
 AND lower(f.category) = lower(s.category)
 AND lower(coalesce(f.address, '')) = lower(coalesce(s.address, ''))
ORDER BY f.id, s.source_name
ON CONFLICT (facility_id) DO UPDATE SET
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    source_record_id = EXCLUDED.source_record_id,
    verification_status = EXCLUDED.verification_status,
    location_precision = EXCLUDED.location_precision,
    coordinate_source_name = EXCLUDED.coordinate_source_name,
    coordinate_source_url = EXCLUDED.coordinate_source_url;
